package ai.learnharness.android;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public class PlanSearchTest {
 @Test public void requestsNativeSearchWithOriginalInstructionsAndNoDuplicateFunction()throws Exception{String prompt="Original researcher instructions";JSONArray functions=new JSONArray().put(new JSONObject("{name:'web_search',description:'original search',parameters:{type:'object'}}")).put(new JSONObject("{name:'web_fetch',description:'original fetch',parameters:{type:'object'}}"));JSONObject body=OpenAiHttp.webSearchBody("test-model",prompt,new JSONArray().put(new JSONObject().put("role","user").put("content","Question")),"default",functions,true);assertEquals(prompt,body.getString("instructions"));assertFalse(body.getBoolean("store"));assertTrue(body.getBoolean("stream"));assertEquals("required",body.getString("tool_choice"));assertEquals(2,body.getJSONArray("tools").length());assertEquals("web_fetch",body.getJSONArray("tools").getJSONObject(0).getString("name"));assertEquals("web_search",body.getJSONArray("tools").getJSONObject(1).getString("type"));assertTrue(body.getJSONArray("tools").getJSONObject(1).getBoolean("external_web_access"));assertFalse(body.has("max_output_tokens"));assertEquals(2,functions.length());}
 @Test public void citationLinksBecomeReadableWhileNativeHistoryRemainsExact()throws Exception{JSONObject nativeOutput=new JSONObject("{responses:[{type:'message',content:[{type:'output_text',text:'Answer',annotations:[{type:'url_citation',title:'Android [Docs]',url:'https://developer.android.com/guide'},{type:'url_citation',title:'duplicate',url:'https://developer.android.com/guide'},{type:'url_citation',title:'unsafe',url:'javascript:bad'}]}]}]}");String original=nativeOutput.toString();ProviderClient.Reply reply=new ProviderClient.Reply("Answer \uE200cite\uE202source\uE201",3,4,new JSONArray(),nativeOutput);ProviderClient.Reply formatted=WebCitations.readable(reply);assertFalse(formatted.text().contains("\uE200"));assertTrue(formatted.text().contains("[Android (Docs)](https://developer.android.com/guide)"));assertEquals(1,WebCitations.sources(reply).length());assertEquals(original,nativeOutput.toString());assertEquals(3,formatted.inputTokens());}
 @Test public void uncitedPlainRepliesRemainUnchanged()throws Exception{ProviderClient.Reply reply=new ProviderClient.Reply("Plain reply",0,0);assertSame(reply,WebCitations.readable(reply));}
}
